INSERT OR REPLACE INTO knowledge_entries(id,category,title,content,language,active,created_at,updated_at) VALUES
('kb-es-profile','perfil','¿Quién es la Dra. Ydania?','La Dra. Ydania Karolis Suárez Sansevero es Médico Cirujano con 30 años de trayectoria profesional y profesora asistente. Es reconocida por su experiencia en medicina estética, obesidad, control de peso y metabolismo, conducta alimentaria y armonización facial. Su formación incluye estudios superiores en Medicina Estética, posgrado en Obesidad en la Universidad Favaloro, formación internacional en obesidad, armonización facial, adicción alimentaria y técnicas de atención al paciente. Su enfoque combina criterio médico, experiencia clínica y una atención orientada a resultados naturales, seguros y personalizados después de una valoración profesional.','es',1,datetime('now'),datetime('now')),
('kb-en-profile','profile','Who is Dr. Ydania?','Dr. Ydania Karolis Suárez Sansevero is a physician and surgeon with 30 years of professional experience and an assistant professor. She is recognized for her expertise in aesthetic medicine, obesity, weight and metabolism management, eating behavior, and facial harmonization. Her training includes advanced studies in Aesthetic Medicine, postgraduate study in Obesity at Universidad Favaloro, international obesity education, facial harmonization, food addiction, and patient-care techniques. Her approach combines medical judgment, clinical experience, and a focus on natural, safe, individualized results after professional evaluation.','en',1,datetime('now'),datetime('now'));
